  }, []);

  const addMerch = useCallback(async () => {
    const baseRecord = { reference: `M${Date.now()}`, client_name: '', produit: '', prix_achat: 0, prix_vente: 0, status: MerchStatus.EN_LIVRAISON, created_at: new Date().toISOString() };
