    <content><![CDATA[
import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeSiteweb, CommandeMerch, Offre, InventoryItem, Charge, MarketingService as MarketingServiceType, MarketingSpend, Retour,
  Payout, PayoutStatus, Credit, CreditStatus,
  CalculatedGros, CalculatedSiteweb, CalculatedMerch, CalculatedMarketing
} from './types';

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL || '';
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY || '';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

interface FournisseurLedger {
  id: number;
  fournisseur_id: number;
  amount: number;
  date: string;
  type: string;
  notes: string;
  created_at: string;
}

interface Fournisseur {
    id: number;
    nom: string;
    contact: string;
    email: string;
    telephone: string;
    adresse: string;
    notes: string;
    created_at: string;
    updated_at: string;
}

interface FournisseurState {
    fournisseurs: Fournisseur[];
    ledgers: FournisseurLedger[];
    loading: boolean;
    error: string | null;
}

const initialFournisseurState: FournisseurState = {
    fournisseurs: [],
    ledgers: [],
    loading: false,
    error: null,
};

const FournisseurContext = createContext<{
  state: FournisseurState;
  dispatch: React.Dispatch<FournisseurAction>;
} | undefined>(undefined);

const fournisseurReducer = (state: FournisseurState, action: FournisseurAction): FournisseurState => {
  switch (action.type) {
    case 'FETCH_FOURNISSEURS_REQUEST':
      return { ...state, loading: true, error: null };
    case 'FETCH_FOURNISSEURS_SUCCESS':
      return { ...state, loading: false, fournisseurs: action.payload, error: null };
    case 'FETCH_FOURNISSEURS_FAILURE':
      return { ...state, loading: false, error: action.payload };
