                  </td>
                  <td className="p-2 text-center">
                    <div className="flex items-center justify-center gap-1">
                      <button 
                        onClick={() => updateGros(item.id, { processed: !item.processed })} 
                        title="Marquer comme traité"
                        className={`p-2 transition-all rounded-lg ${item.processed ? 'text-emerald-500 bg-emerald-50' : 'text-slate-300 hover:text-slate-600 hover:bg-slate-100'}`}
                      >
                        <ClipboardCheck size={18} />
                      </button>
                      <button onClick={(e) => handleDelete(e, item.id)} className="p-2 text-slate-300 hover:text-red-500 rounded-lg hover:bg-red-50">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={9} className="p-32 text-center">
                    <div className="flex flex-col items-center gap-4 text-slate-200">
                      <Truck size={64} />
                      <p className="text-sm font-black uppercase tracking-widest text-slate-300">Aucune commande trouvée</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

